// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 difficulty, uint256 betAmount) public {
        // Bound inputs to reasonable values (avoid overflow issues)
        vm.assume(difficulty < 1e30);
        vm.assume(betAmount < 1e30);

        // Set difficulty to a known value
        c.AdjustDifficulty(difficulty);
        // Then call AdjustBetAmounts (the mutation trigger)
        c.AdjustBetAmounts(betAmount);
        // The rule: currentDifficulty should still be the value we set, not 1
        assertTrue(c.currentDifficulty() == difficulty);
    }
}

